            aOrbiterJ = ((aOrbiterJ ^ aOrbiterA) ^ 0x20472EDDC69919B0ULL) ^ aOUSaltD[((aIndex + 413U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x0E4AC917ED9652B9ULL), 23U);
