            aOrbiterE = ((aWandererA + RotL64(aScatter, 5U)) + 0x99D766F2B876D473ULL) + aOASaltE[((aIndex + 24U)) & S_SALT1];
            aOrbiterC = (((aWandererK + RotL64(aCross, 13U)) + RotL64(aCarry, 27U)) + 0x4FED3F6470AF3456ULL) + aOASaltH[(((511U - aIndex) + 400U)) & S_SALT1];
            aOrbiterJ = ((aWandererD + RotL64(aScatter, 53U)) + 0x8F1EA463E2ABCAAAULL) + aOASaltA[(((511U - aIndex) + 501U)) & S_SALT1];
