            aIngress ^= (RotL64(aEarthLaneA[((aIndex + 11347U)) & S_BLOCK1], 52U) ^ RotL64(pCrossLaneA[((S_BLOCK1 - aIndex + 15937U)) & S_BLOCK1], 21U));
            aIngress = TwistMix64::DiffuseB((aIngress ^ aTwistDomainWordIngress));
            //
            aCross = (RotL64(aWaterLaneD[((S_BLOCK1 - aIndex + 10182U)) & S_BLOCK1], 57U) ^ RotL64(aWaterLaneB[((S_BLOCK1 - aIndex + 9419U)) & S_BLOCK1], 4U));
            aCross ^= (RotL64(pCrossLaneD[((S_BLOCK1 - aIndex + 15082U)) & S_BLOCK1], 37U) ^ RotL64(pCrossLaneC[((S_BLOCK1 - aIndex + 11675U)) & S_BLOCK1], 47U));
            aCross = TwistMix64::DiffuseC((aCross ^ aTwistDomainWordCross));
            //
            aScatter = (RotL64(aCross, 57U) ^ RotL64(aPrevious, 21U)) + (RotL64(aIngress, 40U) + RotL64(aCarry, 5U));
