            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterJ = ((aWandererH + RotL64(aPrevious, 39U)) + RotL64(aCarry, 19U)) + 0x338E2B96AF10CBBFULL;
            aOrbiterE = (aWandererF + RotL64(aScatter, 5U)) + 0xDCE264BD44DAAAF2ULL;
            aOrbiterG = ((aWandererJ + RotL64(aCross, 43U)) + RotL64(aCarry, 47U)) + 0xB3443667C5377EACULL;
            aOrbiterK = (((aWandererG + RotL64(aIngress, 28U)) + RotL64(aCarry, 11U)) + 0x0DEE1559B2A92DE8ULL) + aOASaltD[((aIndex + 297U)) & S_SALT1];
            aOrbiterB = ((aWandererD + RotL64(aPrevious, 13U)) + 0x2144591827DDD8D7ULL) + aOASaltH[(((511U - aIndex) + 343U)) & S_SALT1];
            aOrbiterI = ((aWandererE + RotL64(aIngress, 23U)) + 0x16CD18A75942E2B1ULL) + aOASaltB[((aIndex + 476U)) & S_SALT1];
            aOrbiterC = (aWandererK + RotL64(aScatter, 35U)) + 0x56BE8CA4ECA703AEULL;
            aOrbiterH = (aWandererI + RotL64(aCross, 51U)) + 0xA3C71D4BA6CE5DA3ULL;
            aOrbiterD = (aWandererB + RotL64(aIngress, 58U)) + 0x23969047E1F6BA1EULL;
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterE) + 0x05D3235E66E747E9ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterJ) ^ 0x12FCE527F4448094ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x6F3E4635964D7B07ULL), 23U);
            //
