            aOrbiterB = RotL64((aOrbiterB * 0x6EE4C848F1B91D57ULL), 21U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterG) + 0xDA68F7C6DC457C8BULL) + aOUSaltE[((aIndex + 147U)) & S_SALT1];
            aOrbiterD = ((aOrbiterD ^ aOrbiterC) ^ 0x3E642C9B4FCF7A1BULL) ^ aOUSaltA[(((511U - aIndex) + 389U)) & S_SALT1];
